@classmethod
def parse_index_server(cls, line):
    """

    :param line:
    :return:
    """
    groups = re.split(pattern="[=\s]+", string=line.strip(), maxsplit=100)

    if len(groups) >= 2:
        return groups[1] if groups[1].endswith("/") else groups[1] + "/"

    return None

